event = input or {}
path = event.get('path')
event_type = event.get('event_type') or event.get('event') or 'modified'
if event.get('is_directory') or not path:
    output = {'path': None, 'event_type': event_type, 'skip': True}
else:
    output = {'path': path, 'event_type': event_type, 'skip': False}

import json, os
parts = input if isinstance(input, list) else [input]
path_info = {}
agent_result = {}
for part in parts:
    if isinstance(part, dict) and 'path' in part:
        path_info = part
    elif isinstance(part, dict) and 'response' in part:
        agent_result = part
raw = agent_result.get('response', {}).get('content') if isinstance(agent_result, dict) else agent_result
if not isinstance(raw, str):
    raw = json.dumps(raw, ensure_ascii=False)
try:
    decision = json.loads(raw)
except Exception:
    decision = {'ingest': False, 'reason': f'Invalid JSON from curator: {raw[:200]}'}
path = path_info.get('path')
event_type = path_info.get('event_type') or 'modified'
metadata = {
    'source_type': 'file',
    'path': path,
    'event_type': event_type,
    'summary': decision.get('summary'),
    'reason': decision.get('reason')
}
if isinstance(decision.get('tags'), list):
    metadata['tags'] = decision.get('tags')
filename = decision.get('title') or (os.path.basename(path) if path else 'document.txt')
if decision.get('ingest') and path:
    output = [{'path': path, 'filename': filename, 'metadata': metadata}]
else:
    output = []
